export const BODY: string = "\n<p>PNG کو WebP میں بدلنا ویب سائٹ کے لیے سب سے فائدہ مند تبدیلی ہے: فائل 70 فیصد تک چھوٹی ہو جاتی ہے، اور شفافیت بھی بچ جاتی ہے۔ یہ وہ تبدیلی ہے جو JPG نہیں دے سکتا۔</p>\n<p>PNG کی بڑی فائل ویب سائٹ کو سست کر دیتی ہے، خاص طور پر جب لوگو، آئیکن اور ہیرو تصویریں PNG میں ہوں۔ WebP میں بدلنے سے صفحہ تیزی سے کھلتا ہے۔</p>\n<p>یہ رہنما بتاتا ہے کہ WebP کتنا چھوٹا ہے، شفافیت کیسے بچتی ہے، کون سی سیٹنگ کام کرتی ہے، اور آئیکن سیٹ کو بیچ میں کیسے بدلیں۔ تبدیل کرنے کے لیے <a href=\"/ur/png-ko-webp-mein-convert-karein/\">PNG ٹو WebP</a> استعمال کریں۔</p>\n<h2 id=\"what-is-png-to-webp\">PNG ٹو WebP تبدیلی کیا ہے؟</h2>\n<p>PNG کے پکسلز کو WebP فارمیٹ میں دوبارہ لکھا جاتا ہے، جس سے فائل بہت چھوٹی ہو جاتی ہے۔ شفافیت بچتی ہے، اس لیے لوگو اور آئیکن ویسے ہی نظر آتے ہیں۔</p>\n<p>تبدیلی بغیر نقصان یا نقصان دہ، دونوں طریقوں سے ہو سکتی ہے۔ بغیر نقصان موڈ میں تصویر بالکل ویسی رہتی ہے، مگر فائل کم چھوٹی ہوتی ہے۔</p>\n<p>یہ تبدیلی ویب کے لیے بنائی گئی ہے، جہاں فائل سائز اور شفافیت دونوں اہم ہیں۔ پرنٹ کے لیے PNG ہی رکھیں۔</p>\n<h2 id=\"how-much-smaller\">WebP PNG سے کتنا چھوٹا ہے؟</h2>\n<p>WebP PNG سے 60 سے 80 فیصد چھوٹا ہو سکتا ہے۔ 1MB PNG لوگو WebP میں 200KB بن سکتا ہے، بغیر نظر آنے والا فرق۔</p>\n<p>بچت تصویر کی قسم پر منحصر ہے: سادہ آئیکن میں زیادہ بچت، تفصیل والی تصویر میں کم۔ لیکن ہر تصویر میں بچت ضرور ہوتی ہے۔</p>\n<p>پوری ویب سائٹ پر یہ بچت دسیوں میگا بائٹ بنتی ہے۔ صفحہ تیزی سے کھلتا ہے اور وزیٹر خوش رہتا ہے۔</p>\n<h2 id=\"transparency-preserved\">شفافیت محفوظ رہتی ہے</h2>\n<p>WebP PNG کی طرح شفافیت بچاتا ہے، اس لیے شفاف لوگو WebP میں بھی شفاف رہتا ہے۔ یہ JPG سے WebP کا سب سے بڑا فائدہ ہے۔</p>\n<p>شفافیت جانچنے کے لیے تبدیل شدہ تصویر کو رنگین پس منظر پر دیکھیں۔ اگر لوگو کے گرد سفید ڈبہ نہ ہو تو شفافیت بچ گئی ہے۔</p>\n<p>شفافیت کے ساتھ WebP فائل PNG سے بہت چھوٹی ہوتی ہے، اس لیے ویب لوگو کے لیے WebP بہترین ہے۔</p>\n<h2 id=\"quality-settings\">معیار کی سیٹنگز جو کام کرتی ہیں</h2>\n<p>نقصان دہ موڈ میں 80 سے 85 معیار بہترین ہے: فائل چھوٹی اور تصویر تیز۔ بغیر نقصان موڈ میں معیار کا سوال نہیں، تصویر بالکل ویسی رہتی ہے۔</p>\n<p>لوگو اور آئیکن کے لیے بغیر نقصان موڈ چنیں، کیونکہ ان میں تیز کنارے ہوتے ہیں۔ فوٹو کے لیے نقصان دہ موڈ کافی ہے۔</p>\n<p>سیٹنگ چننے کے بعد نتیجہ کو مکمل سائز میں دیکھیں۔ اگر تصویر صاف لگے تو سیٹنگ درست ہے۔</p>\n<h2 id=\"icon-sets\">پورے آئیکن سیٹ کو تبدیل کرنا</h2>\n<p>آئیکن سیٹ میں درجنوں چھوٹے آئیکن ہوتے ہیں، جنہیں بیچ میں ایک ساتھ WebP میں بدلا جا سکتا ہے۔ یہ بہت وقت بچاتا ہے۔</p>\n<p>آئیکن سیٹ بدلتے وقت بغیر نقصان موڈ چنیں، تاکہ تیز کنارے محفوظ رہیں۔ بیچ کا نتیجہ ZIP میں ملتا ہے۔</p>\n<p>بیچ بدلنے سے پہلے ایک آئیکن آزمائیں۔ اگر وہ صاف لگے تو پوری سیٹ بدلیں۔</p>\n<h2 id=\"screenshots-with-text\">متن والے اسکرین شاٹ</h2>\n<p>اسکرین شاٹ میں متن ہوتا ہے، جو WebP میں PNG سے تھوڑا نرم ہو سکتا ہے۔ متن کے لیے 85 سے اوپر معیار رکھیں، یا بغیر نقصان موڈ چنیں۔</p>\n<p>اگر متن سب سے اہم ہو تو PNG ہی رکھیں۔ WebP متن کے لیے اچھا ہے، مگر PNG سب سے تیز ہے۔</p>\n<p>اسکرین شاٹ کو WebP میں بدلنے سے پہلے متن کو زوم کر کے دیکھیں۔ اگر متن صاف پڑھا جائے تو تبدیلی کامیاب ہے۔</p>\n<h2 id=\"hero-images\">ویب سائٹس کی ہیرو تصویریں</h2>\n<p>ہیرو تصویر صفحے کی سب سے بڑی تصویر ہوتی ہے، اس لیے اس کی فائل سب سے اہم ہے۔ PNG ہیرو تصویر کو WebP میں بدلنے سے صفحہ بہت تیز ہو جاتا ہے۔</p>\n<p>ہیرو تصویر کے لیے 85 معیار رکھیں، کیونکہ وہ سب سے زیادہ نظر آتی ہے۔ کم معیار پر ہیرو تصویر غیر پیشہ ورانہ لگتی ہے۔</p>\n<p>ہیرو تصویر بدلنے کے بعد PageSpeed سے LCP جانچیں۔ بہتری فوراً نظر آئے گی۔</p>\n<h2 id=\"metadata-and-colour\">میٹا ڈیٹا اور رنگ پروفائل</h2>\n<p>تبدیلی کے دوران میٹا ڈیٹا اکثر ہٹا دیا جاتا ہے، جو پرائیویسی کے لیے اچھا ہے۔ رنگ پروفائل بھی بدل سکتا ہے، اس لیے نتیجہ کا رنگ اصل سے ملا کر دیکھیں۔</p>\n<p>اگر رنگ بدل جائیں تو رنگ پروفائل بچانے والا ٹول استعمال کریں۔ زیادہ تر تصویروں میں رنگ کا فرق نظر نہیں آتا۔</p>\n<p>رنگ جانچنے کے لیے تبدیل شدہ تصویر کو اصل کے ساتھ ساتھ دیکھیں۔ اگر رنگ ایک جیسے لگیں تو تبدیلی درست ہے۔</p>\n<h2 id=\"when-webp-is-larger\">WebP بڑا کب نکلتا ہے</h2>\n<p>چھوٹی اور سادہ PNG تصویریں WebP میں بڑی ہو سکتی ہیں، کیونکہ WebP کا ہیڈر بڑا ہوتا ہے۔ ایسی صورت میں PNG ہی رکھیں۔</p>\n<p>بغیر نقصان موڈ میں بھی فائل بڑی ہو سکتی ہے، اگر تصویر میں بہت تفصیل ہو۔ تبدیلی کے بعد فائل کا سائز ہمیشہ جانچیں۔</p>\n<p>اگر WebP بڑا ہو تو اسے مسترد کر کے PNG رکھیں۔ تبدیلی کا مقصد فائل چھوٹی کرنا ہے، بڑی کرنا نہیں۔</p>\n<h2 id=\"png-vs-jpg-decision\">PNG ٹو WebP یا PNG ٹو JPG؟</h2>\n<p>اگر شفافیت چاہیے تو WebP چنیں، کیونکہ JPG شفافیت مٹا دیتا ہے۔ اگر مطابقت چاہیے تو JPG چنیں، کیونکہ وہ ہر جگہ کھلتا ہے۔</p>\n<p>ویب کے لیے WebP بہتر ہے، شیئرنگ کے لیے JPG بہتر ہے۔ دونوں PNG سے بہت چھوٹے ہیں۔</p>\n<p>شک ہو تو دونوں نسخے بنائیں: ویب کے لیے WebP اور شیئرنگ کے لیے JPG۔ اصل PNG محفوظ رکھیں۔</p>\n<h2 id=\"checking-quality\">ڈاؤن لوڈ سے پہلے معیار جانچنا</h2>\n<p>ڈاؤن لوڈ سے پہلے تصویر کو مکمل سائز میں دیکھیں اور اصل سے موازنہ کریں۔ شفافیت، متن اور رنگ جانچیں۔</p>\n<p>اگر فرق نظر نہ آئے تو معیار درست ہے۔ اگر شفافیت ختم ہو گئی ہو تو دوبارہ تبدیل کریں۔</p>\n<p>جانچ کے لیے پیش منظر پر بھروسہ نہ کریں۔ چھوٹے پیش منظر پر نقصان چھپ جاتا ہے۔</p>\n<h2 id=\"common-mistakes\">عام غلطیاں جن سے بچیں</h2>\n<p>سب سے عام غلطی شفاف لوگو کو JPG میں بدلنا ہے۔ دوسری غلطی معیار کو بہت کم رکھنا ہے، جس سے متن دھندلا ہو جاتا ہے۔</p>\n<p>تیسری غلطی اصل PNG کو مٹا دینا ہے۔ اصل محفوظ رکھیں، تاکہ بعد میں دوبارہ تبدیل کر سکیں۔</p>\n<p>چوتھی غلطی WebP کو پرنٹ کے لیے استعمال کرنا ہے۔ پرنٹ کے لیے PNG یا JPG چنیں۔</p>\n<h2 id=\"webp-for-website-logos\">ویب سائٹ لوگو کے لیے WebP</h2>\n<p>ویب سائٹ لوگو WebP میں بہت چھوٹا ہوتا ہے، اس لیے صفحہ تیزی سے کھلتا ہے۔ شفاف لوگو WebP میں بھی شفاف رہتا ہے۔</p>\n<p>لوگو کے لیے بغیر نقصان موڈ چنیں، تاکہ تیز کنارے محفوظ رہیں۔ لوگو چھوٹا ہوتا ہے، اس لیے فائل کی بچت بھی زیادہ ہوتی ہے۔</p>\n<p>لوگو کی PNG نقل بھی رکھیں، تاکہ پرانے براؤزر والے بھی لوگو دیکھ سکیں۔</p>\n<h2 id=\"webp-for-app-icons\">ایپ آئیکن کے لیے WebP</h2>\n<p>ایپ آئیکن WebP میں چھوٹے اور تیز ہوتے ہیں۔ لیکن ایپ اسٹور اکثر PNG مانگتا ہے، اس لیے اسٹور کے لیے PNG رکھیں۔</p>\n<p>ایپ کے اندر استعمال ہونے والے آئیکن WebP میں رکھیں، تاکہ ایپ ہلکی رہے۔ ایپ کا سائز صارف کے لیے اہم ہے۔</p>\n<p>آئیکن کا سائز بھی درست رکھیں: غلط سائز کا آئیکن مسترد ہو جاتا ہے۔</p>\n<h2 id=\"webp-for-blog-images\">بلاگ تصویروں کے لیے WebP</h2>\n<p>بلاگ میں درجنوں تصویریں ہوتی ہیں، اس لیے WebP سے صفحہ بہت ہلکا ہو جاتا ہے۔ قاری تیزی سے صفحہ کھولتا ہے اور زیادہ دیر رکتا ہے۔</p>\n<p>بلاگ کی ہر PNG تصویر کو WebP میں بدلیں، مگر ہیرو تصویر کا معیار 85 رکھیں۔</p>\n<p>بلاگ میں WebP استعمال کرنے سے گوگل کی درجہ بندی بھی بہتر ہوتی ہے، کیونکہ رفتار درجہ بندی کا حصہ ہے۔</p>\n<h2 id=\"webp-for-ecommerce\">ای کامرس کے لیے WebP</h2>\n<p>دکان میں درجنوں مصنوعات کی تصویریں ہوتی ہیں، اس لیے WebP سے صفحہ تیزی سے کھلتا ہے اور فروخت بڑھتی ہے۔</p>\n<p>مصنوعات کی تصویر میں رنگ درست ہونا چاہیے، اس لیے معیار 85 رکھیں۔ کم معیار پر مصنوعات کا رنگ بدل جاتا ہے۔</p>\n<p>دکان کی ہر تصویر کو WebP میں بدلیں، مگر اصل PNG بھی محفوظ رکھیں۔</p>\n<h2 id=\"webp-for-social-graphics\">سوشل میڈیا گرافکس کے لیے WebP</h2>\n<p>سوشل گرافکس WebP میں چھوٹے ہوتے ہیں، مگر پلیٹ فارم انہیں خود بدل دیتا ہے۔ اپ لوڈ سے پہلے پلیٹ فارم کی حمایت جانچیں۔</p>\n<p>اگر پلیٹ فارم WebP نہ لے تو JPG استعمال کریں۔ سوشل میڈیا پر مطابقت سائز سے زیادہ اہم ہے۔</p>\n<p>سوشل گرافکس کے لیے اصل PNG رکھیں اور پلیٹ فارم کے لیے JPG نسخہ بنائیں۔ PNG اور WebP کا موازنہ <a href=\"/ur/blog/png-vs-webp/\">PNG بمقابلہ WebP</a> میں اور عملی مراحل <a href=\"/ur/blog/png-ko-webp-mein-kaise-convert-karein/\">PNG کو WebP میں کیسے بدلیں</a> میں دیکھیں۔ JPG چاہیے ہو تو <a href=\"/ur/png-ko-jpg-mein-convert-karein/\">PNG ٹو JPG</a> استعمال کریں۔</p>\n";

